// Normalize ERP OrderLine -> /supos/J2_ERP_OrderLine
var p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { node.warn('ERP bad JSON'); return null; } }
if (!p || typeof p !== 'object') { return null; }
if (p.business_key === undefined || p.order_line_ref === undefined || p.required_qty === undefined) {
    node.warn('ERP missing required fields'); return null;
}
var qty = parseFloat(p.required_qty);
if (isNaN(qty)) { return null; }
var now = Date.now();
msg.payload = {
    businessKey: String(p.business_key),
    orderLineRef: String(p.order_line_ref),
    requiredQty: qty,
    dueAt: p.due_at !== undefined ? String(p.due_at) : '',
    sourceTime: p.event_time !== undefined ? String(p.event_time) : '',
    timeStamp: now,
    quality: 0
};
msg.topic = '/supos/J2_ERP_OrderLine';
return msg;

